/* Standalone interaction model. Demo storage only; no API, device or payment calls.
   Production wiring and preserved business rules are documented in HANDOFF.md. */
'use strict';
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => Number(n || 0).toLocaleString('en-CA');
const money = n => new Intl.NumberFormat('en-CA', {style:'currency',currency:'CAD'}).format(n || 0);
const TODAY = '2026-10-16';
const KEY = 'rc_scale_design_demo_v1';
const seed = () => ({connected:true, weight:18420,material:0,nextId:162,camera:true,settings:{mode:'assisted',prompt:'ask',delay:'3',single:true,plates:false,printer:'Epson TM-T88VI',autoPrint:true,photos:true,autoCharge:false,terminal:'Scale House Terminal',source:'Yard camera',baud:'9600',protocol:'Western APX'},materials:[{name:'Mixed Tires',rate:.14},{name:'Off-Road / Agricultural Tires',rate:.10},{name:'Passenger & Light Truck Tires',rate:.14},{name:'Scrap Metal',rate:.45},{name:'Asphalt Shingles',rate:.08},{name:'Commercial Truck Tires',rate:.12}],customers:['Kal Tire — Edmonton South','Prairie Tire & Auto','Northland Recycling','Alberta Roadworks','Westside Tire Service'],tickets:[{id:160,customer:'Kal Tire — Edmonton South',plate:'BTR 4821',driver:'Alex Morgan',phone:'',material:'Mixed Tires',rate:.14,gross:18420,tare:0,status:'open',date:TODAY,time:'08:32',payment:'unpaid',notes:'',type:'dropoff'},{id:161,customer:'',plate:'CJL 9018',driver:'',phone:'',material:'Asphalt Shingles',rate:.08,gross:12680,tare:0,status:'open',date:TODAY,time:'08:44',payment:'unpaid',notes:'',type:'dropoff'},{id:159,customer:'Prairie Tire & Auto',plate:'CKN 2034',driver:'Jordan Lee',material:'Mixed Tires',rate:.14,gross:18500,tare:8200,status:'completed',date:TODAY,time:'08:15',payment:'card',notes:'',type:'dropoff'},{id:158,customer:'Northland Recycling',plate:'BXP 7162',driver:'Sam Taylor',material:'Mixed Tires',rate:.14,gross:16440,tare:7800,status:'completed',date:TODAY,time:'07:52',payment:'cash',notes:'',type:'dropoff'},{id:157,customer:'Westside Tire Service',plate:'CBR 3056',driver:'Casey Brown',material:'Mixed Tires',rate:.14,gross:13200,tare:7460,status:'completed',date:TODAY,time:'07:28',payment:'unpaid',notes:'',type:'dropoff'},{id:156,customer:'Alberta Roadworks',plate:'CLP 4207',driver:'Morgan Smith',material:'Asphalt Shingles',rate:.08,gross:23440,tare:9400,status:'completed',date:'2026-10-15',time:'15:40',payment:'card',notes:'',type:'dropoff'}],log:['Station ready · 08:00'],settled:false});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}
let materialPhoto='',materialPhotoReading=false,materialPhotoVersion=0;
let page='workspace',period='today',selectedTicket=null,toastTimer,modalTrigger=null;
const ticketNumber = t => 'RC-2026-'+String(t.id).padStart(5,'0');
const net = t => t.status==='completed'?Math.max(0,t.gross-t.tare):0;
const total = t => Math.round(net(t)*t.rate*1.05*100)/100;
const getTicket = id => state.tickets.find(t=>t.id===Number(id));
const save = () => {try{localStorage.setItem(KEY,JSON.stringify(state))}catch{} render()};
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function record(text){state.log.unshift(text);state.log=state.log.slice(0,20)}
function close(){ $('modal').close();if(modalTrigger?.isConnected)modalTrigger.focus() }
function modal(title,body,eyebrow='SCALE HOUSE'){$('modal').classList.remove('camera-wide','camera-fullscreen');if(!$('modal').open)modalTrigger=document.activeElement;$('modal-title').textContent=title;$('modal-eyebrow').textContent=eyebrow;$('modal-body').innerHTML=body;$('modal-body').querySelectorAll('button:not([type])').forEach(b=>b.type='button');if(!$('modal').open)$('modal').showModal();$('modal-body').scrollTop=0}
const actions = (html) => '<div class="modal-actions"><button class="button" data-action="close">Cancel</button>'+html+'</div>';
function go(target){page=target;document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!==target);document.querySelectorAll('[data-page]').forEach(el=>{el.classList.toggle('active',el.dataset.page===(['vault','unattended'].includes(target)?'equipment':target));el.classList.toggle('selected',el.dataset.page===(['vault','unattended'].includes(target)?'equipment':target)&&el.classList.contains('rail-btn'))});$('page-title').innerHTML=({workspace:'Scale House',history:'Ticket history',equipment:'Station setup',vault:'Photo Vault',unattended:'Unattended station'}[target])+'<span class="title-dot">.</span>';$('page-subtitle').textContent=({workspace:'A clear view of every load, from arrival to receipt.',history:'Find a load, check the details, and keep your records in order.',equipment:'Your scale, camera, printer and payments. All in one place.',vault:'Every capture, connected to the visit it belongs to.',unattended:'Driver check-in, weighing and billing—with remote exception handling.'}[target]);render();window.scrollTo({top:0,behavior:'smooth'})}
function filtered(){const q=$('search').value.trim().toLowerCase(),status=$('status-filter').value,material=$('material-filter').value,customer=$('customer-filter').value;return state.tickets.filter(t=>(status==='all'||t.status===status)&&(!material||t.material===material)&&(!customer||(customer==='unassigned'?!t.customer:t.customer===customer.slice(5)))&&(!q||[ticketNumber(t),t.customer,t.plate,t.material].join(' ').toLowerCase().includes(q))&&(period==='all'||period==='today'&&t.date===TODAY||period==='yesterday'&&t.date==='2026-10-15'||period==='week'&&t.date>='2026-10-12'&&t.date<=TODAY||period==='range'&&t.date>=$('date-from').value&&t.date<=$('date-to').value)).sort((a,b)=>b.id-a.id)}
function table(tickets){return tickets.length?'<table><thead><tr><th>TICKET / TIME</th><th>CUSTOMER</th><th>MATERIAL</th><th class="number">NET WEIGHT</th><th class="number">TOTAL</th><th>STATUS</th><th></th></tr></thead><tbody>'+tickets.map(t=>'<tr><td><button data-ticket="'+t.id+'">'+ticketNumber(t)+'</button><span class="table-secondary">'+esc(t.date)+' · '+esc(t.time)+'</span></td><td>'+esc(t.customer||'Customer not assigned')+'<span class="table-secondary">'+esc(t.plate||'No plate recorded')+'</span></td><td>'+esc(t.material)+'</td><td class="number">'+(net(t)?fmt(net(t))+' kg':'—')+'</td><td class="number">'+(net(t)?money(total(t)):'—')+'</td><td><span class="pill '+(t.status==='completed'&&t.payment!=='unpaid'?'good':t.status==='voided'?'bad':'')+'">'+(t.status==='open'?'In yard':t.status==='voided'?'Voided':t.payment==='unpaid'?'Payment due':'Paid · '+esc(t.payment))+'</span></td><td><button data-ticket="'+t.id+'" aria-label="Open '+ticketNumber(t)+'">↗</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">No tickets match these filters. Try another date or search.</div>'}
function render(){syncHistoryFilters();const open=state.tickets.filter(t=>t.status==='open').sort((a,b)=>a.id-b.id),completed=state.tickets.filter(t=>t.status==='completed'&&t.date===TODAY);$('weight').textContent=state.connected?fmt(state.weight):'—';$('weight-state').innerHTML=state.connected?'<span>✓</span> '+(state.weight>0?'Stable reading':'Scale is clear'):'Scale disconnected';$('weight-help').textContent=state.connected?(state.weight>0?'Truck on scale · ready to capture':'Waiting for the next truck'):'Connect Scale Bridge to see live weights';$('scale-dot').classList.toggle('green',state.connected);$('capture-btn').disabled=!state.connected||state.weight<=0;$('connection-chip').textContent=state.connected?'Scale connected ↗':'Connect scale ↗';$('next-action').textContent=state.weight<100?'Waiting for a load':state.weight<10000&&open.length?'Weigh out a truck in the yard':'Capture an arriving load';$('agent-chip').textContent=({assisted:'Assisted mode',off:'Automation off',dry:'Dry run',live:'Auto mode'}[state.settings.mode])+' ↗';$('agent-summary-text').textContent=state.settings.mode==='live'?'Auto mode selected. In this demo, press Capture to preview each action.':'You capture the weight. We keep the ticket, customer and receipt together.';$('material-name').textContent=state.materials[state.material].name;$('material-price').textContent=money(state.materials[state.material].rate)+' / kg';$('yard-count').textContent=open.length;$('history-count').textContent=state.tickets.length;$('stat-completed').textContent=completed.length;$('stat-net').innerHTML=fmt(completed.reduce((a,t)=>a+net(t),0))+' <small>kg</small>';$('stat-revenue').textContent=money(completed.reduce((a,t)=>a+total(t),0));$('yard-list').innerHTML=open.length?open.map((t,i)=>'<article class="yard-row"><div class="position">'+String(i+1).padStart(2,'0')+'</div><div class="yard-info"><div class="yard-title"><button data-ticket="'+t.id+'">'+esc(t.customer||'Unknown · live ticket')+'</button><span class="pill '+(t.customer?'good':'')+'">'+(t.customer?'In yard':'Needs customer')+'</span></div><div class="ticket-meta">'+ticketNumber(t)+' <span>·</span> '+esc(t.material)+'<br><b>'+esc(t.plate||'No plate')+'</b> · Arrived '+t.time+'</div><div class="yard-actions"><button class="button mini" data-assign="'+t.id+'">'+(t.customer?'Edit details':'＋ Assign customer')+'</button><button class="button mini primary" data-weigh="'+t.id+'">Weigh out →</button></div></div><div class="yard-right"><strong>'+fmt(t.gross)+' <small>kg</small></strong><small>Gross weight</small><button class="icon-button" data-void="'+t.id+'" aria-label="Void '+ticketNumber(t)+'">⋯</button></div></article>').join(''):'<div class="empty">The yard is clear. Capture a weight to start the next load.</div>';$('recent-table').innerHTML=table(completed.sort((a,b)=>b.id-a.id).slice(0,3));$('history-table').innerHTML=table(filtered());const shown=filtered();$('history-summary').innerHTML=[['Tickets in view',shown.length],['Net material',fmt(shown.reduce((a,t)=>a+net(t),0))+' kg'],['Total incl. GST',money(shown.reduce((a,t)=>a+total(t),0))]].map(([label,value])=>'<div class="summary-box"><span>'+label+'</span><strong>'+value+'</strong></div>').join('');document.querySelectorAll('[data-weight]').forEach(b=>b.classList.toggle('active',Number(b.dataset.weight)===state.weight));renderCameras();renderEquipment();if(page==='unattended')renderUnattended();renderCockpit()}
function renderEquipment(){const cards=[['branding','◈','Branding & appearance','Your identity','Personalize your business name, logo and station colours.'],['unattended','↗','Unattended station','Interactive demo','Driver QR check-in, simulated licence extraction, vehicle matching and billing.'],['emergency','!','Emergency contact','Email alerts','Choose who receives remote incident alerts. SMS is planned for later.'],['vault','▧','Photo Vault',vaultEvents.filter(e=>e.image).length+' pictures','Find every capture, pair arrivals and departures, and review each truck visit.'],['connection','▣','Truck scale',state.connected?'Connected':'Disconnected','Manage the bridge connection, scale protocol and serial settings.'],['camera','◉','Yard cameras',state.cameras.filter(c=>c.enabled).length+' of '+state.cameras.length+' ready','Switch between camera views and choose which camera supplies ticket photos.'],['agent','✦','Scale automation',({assisted:'Assisted',off:'Off',dry:'Dry run',live:'Live'}[state.settings.mode]),'Choose how much the station does for you, and when it should ask.'],['printer','▤','Receipt printer','Ready','Choose a printer, test a receipt and set automatic printing preferences.'],['pricing','▧','Material pricing',state.materials.length+' materials','Review and edit the rates used for each incoming material.'],['square','▣','Square Terminal',state.settings.autoCharge?'Auto-charge on':'Manual payments','Pair a terminal and choose when a closed ticket is sent for payment.']];$('equipment-grid').innerHTML=cards.map(([id,icon,name,status,description])=>'<article class="equipment-card"><div class="device-icon">'+icon+'</div><h2>'+name+'</h2><p>'+description+'</p><span class="pill good">'+esc(status)+'</span><button class="button" data-setting="'+id+'">Manage '+name.toLowerCase()+' →</button></article>').join('')}
function materialPicker(){modal('What is coming in?','<p class="modal-intro">This material will be used for new tickets. Existing tickets keep their own material and rate.</p><div class="choice-list">'+state.materials.map((m,i)=>'<button class="choice '+(i===state.material?'selected':'')+'" data-material="'+i+'"><span>▧</span><div><strong>'+esc(m.name)+'</strong><small>'+money(m.rate)+' per kg · before GST</small>'+materialDetails(m)+'</div><span class="arrow">'+(i===state.material?'✓':'→')+'</span></button>').join('')+'</div>','YARD MATERIAL')}
function capture(){if(!state.connected||state.weight<=0)return toast('Connect the scale and choose a positive sample weight first.');modal('Weight captured','<div class="captured"><small>STABLE SCALE READING · DEMO</small><strong>'+fmt(state.weight)+' <small>kg</small></strong><small>Choose how to use this reading.</small></div><div class="choice-list"><button class="choice" data-action="arrive"><span>↙</span><div><strong>Arriving load</strong><small>Open a ticket with this gross weight.</small></div><span class="arrow">→</span></button><button class="choice" data-action="depart"><span>↗</span><div><strong>Truck leaving the yard</strong><small>Use this weight to complete an open ticket.</small></div><span class="arrow">→</span></button></div>','CAPTURE & CONTINUE')}
function newTicket(useWeight=false){const mat=state.materials[state.material];modal(useWeight?'New arriving load':'Create a ticket','<p class="modal-intro">'+(useWeight?'Gross weight captured: <b>'+fmt(state.weight)+' kg</b>.':'Enter the gross weight from the scale. This prototype uses sample values.')+'</p><form id="new-form"><label class="field">Customer<select name="customer"><option value="">Assign later · unknown load</option>'+state.customers.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select></label><div class="form-grid"><label class="field">Gross weight (kg)<input name="gross" type="number" min="1" max="100000" required value="'+(useWeight?state.weight:'')+'" '+(useWeight?'readonly':'')+'></label><label class="field">Licence plate<input name="plate" placeholder="e.g. BTR 4821" maxlength="20"></label></div><div class="form-grid"><label class="field">Vehicle<input name="vehicle" maxlength="100" placeholder="e.g. Kenworth T880 dump truck"></label><label class="field">Colour<input name="colour" maxlength="40" placeholder="e.g. White"></label></div><label class="field">Driver name<input name="driver" maxlength="100" placeholder="First and last name"></label><label class="field">Material<select name="material">'+state.materials.map((m,i)=>'<option value="'+i+'" '+(i===state.material?'selected':'')+'>'+esc(m.name)+'</option>').join('')+'</select></label><label class="field">Notes<textarea name="notes" placeholder="Anything the next operator should know?"></textarea></label><div class="callout">The load stays in the yard until you capture its outbound weight.</div>'+actions('<button class="button primary" type="submit">Create ticket →</button>')+'</form>')}
function assign(id){selectedTicket=Number(id);const t=getTicket(id);modal('Load details','<p class="modal-intro">'+ticketNumber(t)+' · '+esc(t.material)+' · '+fmt(t.gross)+' kg in</p><form id="assign-form"><label class="field">Customer<select name="customer"><option value="">Unknown · assign later</option>'+state.customers.map(c=>'<option '+(c===t.customer?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></label><details><summary class="text-button">＋ Add a new customer</summary><label class="field">Company name<input name="newCustomer" placeholder="Company or customer name"></label><label class="field">Contact phone<input name="customerPhone" type="tel" placeholder="Phone number"></label></details><div class="form-grid"><label class="field">Vehicle<input name="vehicle" maxlength="100" value="'+esc(t.vehicle)+'" placeholder="e.g. Kenworth T880 dump truck"></label><label class="field">Colour<input name="colour" maxlength="40" value="'+esc(t.colour)+'" placeholder="e.g. White"></label></div><div class="form-grid"><label class="field">Driver name<input name="driver" value="'+esc(t.driver)+'" placeholder="Name"></label><label class="field">Driver phone<input name="phone" type="tel" value="'+esc(t.phone)+'" placeholder="Phone"></label></div><div class="form-grid"><label class="field">Licence plate<input name="plate" value="'+esc(t.plate)+'" maxlength="20"></label><label class="field">Material<select name="material">'+state.materials.map((m,i)=>'<option value="'+i+'" '+(m.name===t.material?'selected':'')+'>'+esc(m.name)+'</option>').join('')+'</select></label></div><label class="field">Notes<textarea name="notes">'+esc(t.notes)+'</textarea></label>'+actions('<button class="button primary" type="submit">Save details</button>')+'</form>','CUSTOMER & LOAD')}
function departure(){const open=state.tickets.filter(t=>t.status==='open');modal('Which truck is leaving?',open.length?'<p class="modal-intro">Match the truck on the scale with a load in the yard.</p><div class="choice-list">'+open.map(t=>'<button class="choice" data-weigh="'+t.id+'"><span>↗</span><div><strong>'+esc(t.customer||'Unknown · live ticket')+'</strong><small>'+ticketNumber(t)+' · '+esc(t.plate)+' · '+fmt(t.gross)+' kg in</small></div><span class="arrow">→</span></button>').join('')+'</div>':'<div class="empty">No open tickets. Capture an arriving load first.</div>')}
function weighOut(id){selectedTicket=Number(id);const t=getTicket(id),valid=state.connected&&state.weight>0&&state.weight<t.gross;modal('Ready to complete this load?','<p class="modal-intro">'+esc(t.customer||'Unknown · live ticket')+' · '+ticketNumber(t)+'</p><div class="detail-grid"><div><small>GROSS · IN</small><strong>'+fmt(t.gross)+' kg</strong></div><div><small>TARE · NOW</small><strong>'+(state.connected?fmt(state.weight)+' kg':'Offline')+'</strong></div><div class="net"><small>NET MATERIAL</small><strong>'+fmt(Math.max(0,t.gross-state.weight))+' kg</strong></div></div>'+(!valid?'<div class="callout amber">The outgoing weight must be above zero and below the incoming weight. Try the <b>Empty truck</b> scenario, then weigh out again.</div><button class="button" style="margin-top:14px" data-action="empty-for-out">Use empty truck sample · 7,860 kg</button>':'<div class="detail-list"><div><span>Material</span><strong>'+esc(t.material)+'</strong></div><div><span>Rate per kg</span><strong>'+money(t.rate)+'</strong></div><div><span>Estimated total · incl. 5% GST</span><strong>'+money((t.gross-state.weight)*t.rate*1.05)+'</strong></div></div><p class="settings-note">A sample receipt will be created. No printer or payment terminal is contacted.</p>')+actions('<button class="button primary" data-action="complete" '+(!valid?'disabled':'')+'>Complete load →</button>'),'WEIGH OUT')}
function complete(){const t=getTicket(selectedTicket);if(!t||t.status!=='open'||!state.connected||state.weight<=0||state.weight>=t.gross)return toast('Check the outgoing weight before completing.');t.tare=state.weight;t.status='completed';t.payment='unpaid';state.settled=false;captureTicketVault(t,'out');record(ticketNumber(t)+' completed · '+fmt(net(t))+' kg');save();receipt(t.id);toast('Load completed. Sample receipt is ready.')}
function detail(id){selectedTicket=Number(id);const t=getTicket(id);modal(ticketNumber(t),'<div class="callout '+(!t.customer?'amber':'')+'">'+esc(t.customer||'Customer not assigned')+' · '+esc(t.plate||'No plate recorded')+'</div><div class="detail-grid"><div><small>GROSS</small><strong>'+fmt(t.gross)+' kg</strong></div><div><small>TARE</small><strong>'+(t.tare?fmt(t.tare)+' kg':'—')+'</strong></div><div class="net"><small>NET</small><strong>'+(net(t)?fmt(net(t))+' kg':'—')+'</strong></div></div><div class="detail-list"><div><span>Status</span><strong>'+({open:'In yard',completed:'Completed',voided:'Voided'}[t.status])+'</strong></div><div><span>Material</span><strong>'+esc(t.material)+'</strong></div>'+vehicleReceiptRows(t)+'<div><span>Payment</span><strong>'+esc(t.payment)+' · '+money(total(t))+'</strong></div><div><span>Notes</span><strong>'+esc(t.notes||'—')+'</strong></div></div><div style="margin-top:17px"><span class="eyebrow">TICKET ACTIVITY</span><div class="activity-line">'+esc(t.date)+' '+t.time+' · Load weighed in</div>'+(t.status==='completed'?'<div class="activity-line">Load weighed out · sample receipt created</div>':'')+(t.status==='voided'?'<div class="activity-line">Voided: '+esc(t.voidReason)+'</div>':'')+'</div><div class="modal-actions"><button class="button" data-action="close">Close</button>'+(t.status==='open'?'<button class="button" data-assign="'+t.id+'">Edit details</button><button class="button primary" data-weigh="'+t.id+'">Weigh out →</button>':t.status==='completed'?'<button class="button" data-assign="'+t.id+'">Edit details</button><button class="button" data-receipt="'+t.id+'">View receipt</button>'+(t.payment==='unpaid'?'<button class="button primary" data-pay="'+t.id+'">Take payment</button>':''):'')+'</div>','TICKET DETAILS')}
function receipt(id){selectedTicket=Number(id);const t=getTicket(id);modal('Receipt preview','<div class="receipt"><h3>'+esc(brandValue().name.toUpperCase())+'</h3><p>SAMPLE RECEIPT · NOT A REAL TRANSACTION<br>'+ticketNumber(t)+' · '+t.date+'</p><div class="detail-list"><div><span>Customer</span><strong>'+esc(t.customer||'Walk-in')+'</strong></div>'+vehicleReceiptRows(t)+'<div><span>Material</span><strong>'+esc(t.material)+'</strong></div><div><span>Gross / tare</span><strong>'+fmt(t.gross)+' / '+fmt(t.tare)+' kg</strong></div><div><span>Net weight</span><strong>'+fmt(net(t))+' kg</strong></div><div><span>Rate</span><strong>'+money(t.rate)+' / kg</strong></div></div><hr><div class="detail-list"><div><span>Subtotal</span><strong>'+money(net(t)*t.rate)+'</strong></div><div><span>GST (5%)</span><strong>'+money(net(t)*t.rate*.05)+'</strong></div></div><hr><div class="receipt-total"><span>Total CAD</span><strong>'+money(total(t))+'</strong></div><p style="margin:18px 0 0">'+(t.payment==='unpaid'?'PAYMENT DUE':'PAID · '+t.payment.toUpperCase())+'<br>Thank you for recycling with us.</p></div><div class="modal-actions"><button class="button" data-action="print-preview">▤ Print sample</button>'+(t.payment==='unpaid'?'<button class="button primary" data-pay="'+t.id+'">Take payment →</button>':'<button class="button primary" data-action="close">Done</button>')+'</div>','LOAD COMPLETE')}
function payment(id){selectedTicket=Number(id);const t=getTicket(id);modal('How is the customer paying?','<p class="modal-intro">'+ticketNumber(t)+' · '+esc(t.customer||'Walk-in')+'</p><div class="payment-total">'+money(total(t))+'</div><div class="choice-list"><button class="choice" data-payment="card"><span>▣</span><div><strong>Card · Square Terminal</strong><small>Simulate an approved card payment.</small></div><span class="arrow">→</span></button><button class="choice" data-payment="cash"><span>＄</span><div><strong>Cash</strong><small>Mark this sample ticket as paid in cash.</small></div><span class="arrow">→</span></button><button class="choice" data-action="close"><span>◷</span><div><strong>Pay later</strong><small>Keep this ticket unpaid for follow-up.</small></div><span class="arrow">→</span></button></div><p class="screen-only-note">Demo only. No money will be charged.</p>','PAYMENT')}
function voidTicket(id){selectedTicket=Number(id);modal('Void this ticket?','<p class="modal-intro">'+ticketNumber(getTicket(id))+' will be removed from the yard queue and kept in history.</p><form id="void-form"><label class="field">Reason for voiding<textarea name="reason" required placeholder="e.g. Duplicate capture"></textarea></label>'+actions('<button type="submit" class="button danger">Void ticket</button>')+'</form>')}
function settlement(){const tickets=state.tickets.filter(t=>t.status==='completed'&&t.date===TODAY);modal('Today’s payments','<p class="modal-intro">Friday, October 16 · '+tickets.length+' completed loads</p><div class="payment-summary-list">'+['card','cash','unpaid'].map(method=>{const rows=tickets.filter(t=>t.payment===method);return '<button class="payment-summary-row" data-payment-list="'+method+'"><span>'+({card:'Card payments',cash:'Cash payments',unpaid:'Still unpaid'}[method])+' <small>'+rows.length+' tickets</small></span><strong>'+money(rows.reduce((a,t)=>a+total(t),0))+' <span>→</span></strong></button>'}).join('')+'<button class="payment-summary-row" data-payment-list="all"><span>All payments <small>'+tickets.length+' tickets</small></span><strong>'+money(tickets.reduce((a,t)=>a+total(t),0))+' <span>→</span></strong></button></div><p class="settings-note">Select a category to review individual payments. Settling the day does not mark unpaid tickets as paid.</p><div class="modal-actions"><button class="button" data-action="close">Close</button><button class="button primary" data-action="settle" '+(state.settled?'disabled':'')+'>'+(state.settled?'Day settled':'Settle today')+'</button></div>','DAILY SETTLEMENT')}

function camera(){cameraWall()}

const check=(name,title,desc,val)=>'<label class="toggle-row"><span>'+title+'<small>'+desc+'</small></span><input type="checkbox" name="'+name+'" '+(val?'checked':'')+'></label>';
function settings(kind){if(kind==='branding')return brandingSettings();if(kind==='unattended')return openUnattended();if(kind==='emergency')return emergencySettings();if(kind==='vault')return openVault();if(kind==='pricing'){materialPhoto='';materialPhotoReading=false;materialPhotoVersion++;}if(kind==='camera')return cameraManager();if(kind==='connection')return connection();let body='',s=state.settings,title='';if(kind==='agent'){title='Scale automation';body='<p class="modal-intro">Start with assisted weighing. Turn on more automation when your station is ready.</p><label class="field">Operating mode<select name="mode">'+[['assisted','Assisted · operator confirms each load'],['off','Off · no automated actions'],['dry','Dry run · decisions only'],['live','Auto mode · unattended weighing']].map(([v,l])=>'<option value="'+v+'" '+(s.mode===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label><label class="field">After a ticket closes<select name="prompt"><option value="ask" '+(s.prompt==='ask'?'selected':'')+'>Ask for customer details</option><option value="hands-off" '+(s.prompt==='hands-off'?'selected':'')+'>Hands off · assign later</option></select></label><label class="field">Wait before acting<select name="delay">'+['0','3','5'].map(v=>'<option '+(s.delay===v?'selected':'')+' value="'+v+'">'+(v==='0'?'Instant':v+' seconds')+'</option>').join('')+'</select></label>'+check('single','One truck at a time','Flag another arrival while a load is already open.',s.single)+check('plates','Identify trucks by licence plate','Requires a configured camera and plate recognition.',s.plates)+'<p class="settings-note">Automation settings are saved for this prototype. Only Auto mode enables driver check-in and unattended weighing. Other modes use the original manual workflow. Hardware events remain simulated.</p>'}else if(kind==='printer'){title='Receipt printer';body='<div class="printer-select-row"><label class="field">Print to<select name="printer">'+[...new Set(['Epson TM-T88VI',...(state.printers||[]),'Browser print dialog'])].map(v=>'<option '+(s.printer===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><button class="button" type="button" data-action="add-printer">＋ Add printer</button></div>'+check('autoPrint','Print after weigh-out','Create a receipt as soon as the load is completed.',s.autoPrint)+check('photos','Include scale photos','Attach weigh-in and weigh-out photos to the receipt.',s.photos)+'<div style="display:flex;gap:10px;margin-top:20px"><button class="button" type="button" data-action="test-print">Test print</button><button class="button" type="button" data-action="reprint">Reprint last</button></div>'}else if(kind==='camera'){title='Camera settings';body='<label class="field">Camera source<select name="source">'+['Yard camera','USB webcam','Network camera'].map(v=>'<option '+(s.source===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label class="field">Camera address<input name="cameraUrl" value="'+esc(s.cameraUrl||'')+'" placeholder="Enter your camera address"></label>'+check('cameraEnabled','Camera enabled','Keep a visual record of each load.',state.camera)+'<button class="button" type="button" style="margin-top:18px" data-action="test-camera">Test camera</button>'}else if(kind==='pricing'){title='Material pricing';body='<p class="modal-intro">Rates per kilogram, before GST. Changes apply to new sample tickets.</p>'+state.materials.map((m,i)=>'<label class="rate-row"><span>'+esc(m.name)+materialDetails(m)+'</span><span>$ <input type="number" name="rate'+i+'" value="'+m.rate+'" min="0" max="100" step="0.01" required aria-label="'+esc(m.name)+' price per kilogram"></span></label>').join('')+'<details style="margin-top:18px"><summary class="text-button">＋ Add a material</summary><label class="field">Material name<input name="newMaterial" placeholder="Material name"></label><label class="field">Rate per kg<input type="number" name="newRate" min="0" max="100" step=".01" value="0.10"></label><label class="field">Notes <span class="muted">Optional</span><textarea name="newMaterialNotes" maxlength="2000" placeholder="Describe the material, accepted condition or handling instructions…"></textarea></label><label class="field">Attach picture <span class="muted">Optional</span><input id="new-material-picture" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or WebP · under 20 MB · resized for preview and saved only in this browser</small></label><p id="material-photo-error" class="printer-error" role="alert" hidden></p><div id="material-photo-preview" hidden><img id="material-photo-image" alt="Attached material picture"><button class="text-button" type="button" data-action="remove-material-picture">Remove picture</button></div></details>'}else if(kind==='square'){title='Square Terminal';body='<div class="callout">Sample terminal · no connection to Square.</div><label class="field">Terminal<select name="terminal"><option>'+esc(s.terminal)+'</option></select></label>'+check('autoCharge','Auto-charge completed tickets','Production sends eligible tickets to Square after receipt printing.',s.autoCharge)+'<div style="display:flex;gap:10px;margin-top:18px"><button class="button" type="button" data-action="refresh-terminal">↻ Refresh</button><button class="button" type="button" data-action="pair-terminal">Pair a terminal</button></div>'}modal(title,'<form id="settings-form" data-kind="'+kind+'">'+body+actions('<button class="button primary" type="submit">Save settings</button>')+'</form>','EQUIPMENT & SETTINGS')}
function connection(){const s=state.settings;modal('Connect your scale','<div class="callout '+(state.connected?'':'amber')+'">'+(state.connected?'✓ Sample scale connected. The reading is ready to capture.':'Start Scale Bridge on this Mac to see live weights. It links your scale to this page.')+'</div><div class="modal-actions" style="border:0;margin:0;padding:18px 0"><button class="button primary" data-action="toggle-connection">'+(state.connected?'Disconnect sample scale':'Connect sample scale')+'</button></div><details><summary class="text-button">How to start Scale Bridge</summary><ol class="step-list"><li>Open Terminal in the reuse-canada-scale project folder.</li><li>Run <code class="inline-code">node scale-bridge.js</code></li><li>Keep Terminal open, then connect from Scale House.</li></ol><p class="settings-note">This prototype does not connect to your bridge. The button above simulates a connection.</p></details><form id="settings-form" data-kind="connection"><details style="margin-top:18px"><summary class="text-button">Advanced scale settings</summary><div class="form-grid"><label class="field">Baud rate<select name="baud">'+['1200','2400','4800','9600','19200'].map(v=>'<option '+(s.baud===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label class="field">Protocol<select name="protocol">'+['Western APX','ASCII','Toledo','Cardinal'].map(v=>'<option '+(s.protocol===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label></div></details>'+actions('<button type="submit" class="button primary">Save settings</button>')+'</form>','STATION 01')}
function handoff(){modal('Take this design to Claude','<p class="modal-intro">The design is plain HTML, CSS and JavaScript. The handoff explains how to apply it to your existing Hono page while keeping the working scale and payment logic.</p><div class="handoff-links"><a href="claude-ready.zip" download>↓ Download compact Claude package</a><a href="scale-house-prototype.html" download>↓ Download single-file interactive prototype</a><a href="HANDOFF.md" download>↓ Download implementation guide</a><a href="CLAUDE-PROMPT.md" download>↓ Download the prompt for Claude</a></div><div class="modal-actions"><button class="button" data-action="copy-prompt">Copy Claude prompt</button><button class="button primary" data-action="close">Done</button></div>','DESIGN HANDOFF')}
const claudePrompt="Implement the attached final Scale House design in my existing reuse-canada-scale repository. Start with 00-START-HERE.md and 01-FINAL-SPEC.md; use 02-SOURCE-MAP.md to read only relevant code. Follow AGENTS.md and preserve my existing working changes and production functionality. The design decisions are final: implement rather than redesign. Work through the documented checkpoints, reuse existing APIs, and keep a concise progress note to avoid repeating discovery. Demo OCR, hardware, email and payments must never be presented as real integrations. Finish what can be implemented and identify exact missing provider/configuration requirements. Validate the result. Do not deploy, push or run remote migrations yet.\n";
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){const rows=[['Ticket','Date','Customer','Plate','Material','Status','Gross kg','Tare kg','Net kg','Total CAD','Payment'],...filtered().map(t=>[ticketNumber(t),t.date,t.customer,t.plate,t.material,t.status,t.gross,t.tare,net(t),total(t).toFixed(2),t.payment])];download('scale-house-demo-tickets.csv',rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv');toast('Filtered sample tickets exported.')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)return go(b.dataset.page);if(b.dataset.setting)return settings(b.dataset.setting);if(b.dataset.ticket)return detail(b.dataset.ticket);if(b.dataset.assign)return assign(b.dataset.assign);if(b.dataset.weigh)return weighOut(b.dataset.weigh);if(b.dataset.void)return voidTicket(b.dataset.void);if(b.dataset.receipt)return receipt(b.dataset.receipt);if(b.dataset.pay)return payment(b.dataset.pay);if(b.dataset.material!==undefined){state.material=Number(b.dataset.material);save();close();return toast('New loads will use '+state.materials[state.material].name+'.')}if(b.dataset.weight!==undefined){state.weight=Number(b.dataset.weight);$('custom-weight').value=state.weight;save();return}if(b.dataset.period){period=b.dataset.period;document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('active',x===b));$('date-range').hidden=period!=='range';return render()}if(b.dataset.payment){const t=getTicket(selectedTicket);if(t.status!=='completed'||t.payment!=='unpaid')return;t.payment=b.dataset.payment;t.paidAt=new Date().toISOString();t.paymentReference='DEMO-'+t.id+'-'+Date.now();t.paymentActivity=t.paymentActivity||[];t.paymentActivity.push({at:t.paidAt,text:'Sample '+t.payment+' payment recorded',operator:'EG'});state.settled=false;record(ticketNumber(t)+' paid by '+t.payment);save();receipt(t.id);return toast('Sample '+t.payment+' payment recorded. No money charged.')}switch(b.dataset.action){case'close':close();break;case'new':newTicket();break;case'capture':capture();break;case'arrive':newTicket(true);break;case'depart':departure();break;case'material':materialPicker();break;case'empty-for-out':state.weight=7860;state.connected=true;$('custom-weight').value=7860;save();weighOut(selectedTicket);break;case'complete':complete();break;case'connection':connection();break;case'toggle-connection':state.connected=!state.connected;save();connection();toast(state.connected?'Sample scale connected.':'Sample scale disconnected.');break;case'refresh':render();toast('Yard queue is up to date.');break;case'camera':camera();break;case'camera-toggle':state.camera=!state.camera;save();camera();break;case'snapshot':snapshotCamera();break;case'remove-material-picture':clearMaterialPhoto();break;case'add-printer':showAddPrinter();break;case'cancel-add-printer':document.getElementById('add-printer-panel')?.remove();break;case'confirm-add-printer':addDemoPrinter();break;case'test-print':modal('Test receipt','<div class="receipt"><h3>'+esc(brandValue().name.toUpperCase())+'</h3><p>PRINTER TEST · DEMO ONLY</p><hr><p>Station 01<br>80 mm receipt<br>Printer: '+esc(state.settings.printer)+'</p><hr><p>Your receipt layout is ready.</p></div><p class="screen-only-note">Preview only. Nothing was sent to a printer.</p><div class="modal-actions"><button class="button primary" data-action="close">Done</button></div>');break;case'print-preview':toast('Sample print simulated. No paper or printer used.');break;case'reprint':{const t=state.tickets.filter(t=>t.status==='completed').sort((a,b)=>b.id-a.id)[0];if(t)receipt(t.id);else toast('Complete a load first.');break}case'settlement':settlement();break;case'settle':state.settled=true;record('Sample daily settlement recorded');save();settlement();toast('Sample day settled.');break;case'export':exportCSV();break;case'refresh-terminal':toast('Demo terminal found: '+state.settings.terminal);break;case'pair-terminal':modal('Pair a terminal','<p class="modal-intro">Use this sample pairing screen to preview station setup. No real Square pairing request is sent.</p><form id="pair-form"><label class="field">Terminal name<input name="terminal" required placeholder="e.g. Yard Terminal 02"></label><div class="callout">Demo pairing code: <strong>482 916</strong></div>'+actions('<button type="submit" class="button primary">Pair sample terminal</button>')+'</form>');break;case'handoff':handoff();break;case'copy-prompt':try{await navigator.clipboard.writeText(claudePrompt);toast('Claude prompt copied.')}catch{download('CLAUDE-PROMPT.txt',claudePrompt);toast('Prompt downloaded.')}break;case'reset':modal('Reset the demo?','<p class="modal-intro">Restore the original sample tickets, weights and settings. This only clears prototype data.</p>'+actions('<button class="button primary" data-action="confirm-reset">Reset demo</button>'));break;case'clear-history-filters':clearHistoryFilters();render();break;case'confirm-reset':state=seed();$('material-filter').value='';$('customer-filter').value='';period='today';$('search').value='';$('status-filter').value='all';$('date-range').hidden=true;document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('active',b.dataset.period==='today'));$('snapshot-note').hidden=true;$('custom-weight').value=state.weight;save();close();toast('Demo reset. Ready for another run.');break;case'help':modal('Your Scale House workspace','<p class="modal-intro">You are previewing the redesign as sample operator EG. Every action stays in this browser.</p><div class="detail-list"><div><span>Capture a weight</span><kbd>Space</kbd></div><div><span>Create a ticket</span><kbd>N</kbd></div><div><span>Close a dialog</span><kbd>Esc</kbd></div></div><ol class="step-list"><li>Choose Loaded truck and capture an arriving load.</li><li>Assign its customer from the yard queue.</li><li>Choose Empty truck, then weigh out the load.</li><li>Preview the receipt and record a sample payment.</li></ol><button class="button primary" data-action="handoff">Get the Claude handoff →</button>');break}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,d=new FormData(form);if(form.id==='new-form'){const m=state.materials[Number(d.get('material'))];const t={id:state.nextId++,customer:String(d.get('customer')),plate:String(d.get('plate')).trim().toUpperCase(),driver:String(d.get('driver')||'').trim(),vehicle:String(d.get('vehicle')||'').trim(),colour:String(d.get('colour')||'').trim(),phone:'',material:m.name,rate:m.rate,gross:Number(d.get('gross')),tare:0,status:'open',date:TODAY,time:new Date().toLocaleTimeString('en-CA',{hour:'2-digit',minute:'2-digit',hour12:false}),payment:'unpaid',notes:String(d.get('notes')),type:'dropoff'};t.vaultVisit=crypto.randomUUID();state.tickets.push(t);captureTicketVault(t,'in');record(ticketNumber(t)+' opened');save();close();toast('Ticket created. The load is now in the yard.')}else if(form.id==='assign-form'){const t=getTicket(selectedTicket),newCustomer=String(d.get('newCustomer')).trim();if(newCustomer&&!state.customers.includes(newCustomer))state.customers.push(newCustomer);const m=state.materials[Number(d.get('material'))];Object.assign(t,{customer:newCustomer||String(d.get('customer')),driver:String(d.get('driver')).trim(),vehicle:String(d.get('vehicle')||'').trim(),colour:String(d.get('colour')||'').trim(),phone:String(d.get('phone')).trim(),plate:String(d.get('plate')).trim().toUpperCase(),notes:String(d.get('notes')),material:m.name,rate:m.rate});save();close();toast('Load details saved.')}else if(form.id==='void-form'){const t=getTicket(selectedTicket);t.status='voided';t.voidReason=String(d.get('reason')).trim();record(ticketNumber(t)+' voided');save();close();toast('Ticket voided and kept in history.')}else if(form.id==='pair-form'){state.settings.terminal=String(d.get('terminal')).trim();save();settings('square');toast('Sample terminal paired.')}else if(form.id==='settings-form'){const kind=form.dataset.kind;if(kind==='pricing'){
if(materialPhotoReading)return toast('Please wait for the picture to finish loading.');
const name=String(d.get('newMaterial')).trim(),notes=String(d.get('newMaterialNotes')||'').trim();
if(!name&&(notes||materialPhoto))return toast('Enter a material name to save its notes and picture.');
if(name&&state.materials.some(m=>m.name.toLowerCase()===name.toLowerCase()))return toast('That material already exists. Use a different name.');
const previous=state.materials;
state.materials=state.materials.map((m,i)=>({...m,rate:Number(d.get('rate'+i))}));
if(name)state.materials.push({name,rate:Number(d.get('newRate')),notes,picture:materialPhoto});
try{localStorage.setItem(KEY,JSON.stringify(state))}catch{state.materials=previous;return toast('Not enough browser storage. Remove the picture or choose a smaller one.');}
if(name&&materialPhoto)captureMaterialVault(name,notes,materialPhoto);
}else{for(const [k,v]of d.entries())state.settings[k]=v;const bools={agent:['single','plates'],printer:['autoPrint','photos'],square:['autoCharge']}[kind]||[];bools.forEach(k=>state.settings[k]=d.has(k));if(kind==='camera')state.camera=d.has('cameraEnabled')}save();close();toast('Demo settings saved.')}});
$('custom-weight').addEventListener('change',e=>{const n=Number(e.target.value);if(!Number.isFinite(n)||n<0||n>100000){e.target.value=state.weight;return toast('Enter a weight between 0 and 100,000 kg.')}state.weight=n;save()});
['search','status-filter','material-filter','customer-filter','date-from','date-to'].forEach(id=>$(id).addEventListener('input',render));
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('workspace')});
$('close-modal').addEventListener('click',close);$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
document.addEventListener('keydown',e=>{if(e.metaKey||e.ctrlKey||e.altKey||e.repeat||['INPUT','TEXTAREA','SELECT','BUTTON','SUMMARY'].includes(document.activeElement.tagName)||$('modal').open)return;if(e.code==='Space'){e.preventDefault();capture()}if(e.key.toLowerCase()==='n'){e.preventDefault();newTicket()}});
function clock(){const now=new Date();$('clock').textContent=now.toLocaleTimeString('en-CA',{hour:'2-digit',minute:'2-digit'});if($('camera-clock'))$('camera-clock').textContent=now.toLocaleTimeString('en-CA',{hour12:false})}clock();setInterval(clock,1000);$('custom-weight').value=state.weight;render();

function syncHistoryFilters(){
  const materials=[...new Set(state.tickets.map(t=>t.material).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  const customers=[...new Set([...state.customers,...state.tickets.map(t=>t.customer).filter(Boolean)])].sort((a,b)=>a.localeCompare(b));
  for(const [id,options] of [['material-filter','<option value="">All materials</option>'+materials.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('')],['customer-filter','<option value="">All customers</option><option value="unassigned">Unassigned / walk-in</option>'+customers.map(v=>'<option value="name:'+esc(v)+'">'+esc(v)+'</option>').join('')]]){
    const el=$(id),selected=el.value;
    if(el.innerHTML!==options){el.innerHTML=options;el.value=selected;if(el.selectedIndex<0)el.value='';}
  }
  $('clear-history-filters').hidden=!($('search').value||$('material-filter').value||$('customer-filter').value||$('status-filter').value!=='all'||period!=='today');
}
function clearHistoryFilters(){
  $('search').value='';$('status-filter').value='all';$('material-filter').value='';$('customer-filter').value='';period='today';$('date-range').hidden=true;
  document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('active',b.dataset.period==='today'));
}

function showAddPrinter(){
  if($('add-printer-panel'))return $('new-printer-name').focus();
  const panel=document.createElement('div');panel.id='add-printer-panel';panel.className='add-printer-panel';
  panel.innerHTML='<h3>Add a printer</h3><p class="settings-note">Give the printer a name so it is easy to find at this station. This demo saves a sample printer only.</p><label class="field">Printer name<input id="new-printer-name" maxlength="60" placeholder="e.g. Scale House receipt printer"></label><p id="printer-add-error" class="printer-error" role="alert" hidden></p><div class="printer-add-actions"><button class="button" type="button" data-action="cancel-add-printer">Cancel</button><button class="button primary" type="button" data-action="confirm-add-printer">Add printer</button></div>';
  document.querySelector('.printer-select-row').after(panel);$('new-printer-name').focus();
}
function addDemoPrinter(){
  const name=$('new-printer-name').value.trim(),error=$('printer-add-error');
  if(!name){error.textContent='Enter a printer name.';error.hidden=false;$('new-printer-name').focus();return;}
  const select=document.querySelector('#settings-form select[name="printer"]');
  const existing=[...select.options].find(o=>o.value.toLowerCase()===name.toLowerCase());
  if(existing){error.textContent='That printer is already in your list. Choose a different name.';error.hidden=false;return;}
  state.printers=state.printers||[];state.printers.push(name);save();
  select.add(new Option(name,name));select.value=name;$('add-printer-panel').remove();select.focus();
  toast('Printer added. Save settings to use it for receipts.');
}
document.addEventListener('keydown',e=>{if(e.target.id==='new-printer-name'&&e.key==='Enter'){e.preventDefault();addDemoPrinter()}});

function materialDetails(m){return (m.notes?'<small class="material-notes">'+esc(m.notes)+'</small>':'')+(m.picture?'<img class="material-thumbnail" src="'+esc(m.picture)+'" alt="'+esc(m.name)+' reference picture">':'')}
function clearMaterialPhoto(){materialPhotoVersion++;materialPhoto='';materialPhotoReading=false;const input=$('new-material-picture');if(input)input.value='';if($('material-photo-preview'))$('material-photo-preview').hidden=true;if($('material-photo-image'))$('material-photo-image').removeAttribute('src');if($('material-photo-error'))$('material-photo-error').hidden=true;}
document.addEventListener('change',e=>{
 if(e.target.id!=='new-material-picture')return;
 const file=e.target.files[0];clearMaterialPhoto();if(!file)return;
 const error=$('material-photo-error');
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>=20*1024*1024){error.textContent='Choose a JPG, PNG or WebP picture smaller than 20 MB.';error.hidden=false;return;}
 materialPhotoReading=true;const version=materialPhotoVersion,reader=new FileReader();
 reader.onerror=()=>{if(version!==materialPhotoVersion)return;materialPhotoReading=false;error.textContent='This picture could not be read. Try another file.';error.hidden=false;};
 reader.onload=()=>{if(version!==materialPhotoVersion||!$('material-photo-image'))return;const image=new Image();image.onload=()=>{if(version!==materialPhotoVersion||!$('material-photo-image'))return;try{const scale=Math.min(1,1600/image.naturalWidth,1600/image.naturalHeight);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const context=canvas.getContext('2d');context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);materialPhoto=canvas.toDataURL('image/jpeg',.8);}catch{materialPhotoReading=false;error.textContent='This picture could not be prepared. Try another image.';error.hidden=false;return;}materialPhotoReading=false;$('material-photo-image').src=materialPhoto;$('material-photo-preview').hidden=false;};image.onerror=()=>{if(version!==materialPhotoVersion)return;materialPhotoReading=false;error.textContent='This file could not be opened as a picture.';error.hidden=false;};image.src=String(reader.result);};
 reader.readAsDataURL(file);
});

vaultInitPromise=initVault();

function vehicleReceiptRows(t){return [['Vehicle',t.vehicle],['Colour',t.colour],['Licence plate #',t.plate],['Driver name',t.driver]].map(([label,value])=>'<div><span>'+label+'</span><strong>'+esc(value||'Not recorded')+'</strong></div>').join('')}

let paymentListFilter='all';
function paymentList(method='all'){
 paymentListFilter=method;
 const tickets=state.tickets.filter(t=>t.status==='completed'&&t.date===TODAY&&(method==='all'||t.payment===method)).sort((a,b)=>b.id-a.id);
 modal(({card:'Card payments',cash:'Cash payments',unpaid:'Unpaid tickets',all:'All payments'}[method]),'<button class="text-button" data-payment-back="summary">← Today’s payments</button><p class="modal-intro">'+tickets.length+' tickets · '+money(tickets.reduce((a,t)=>a+total(t),0))+' total · October 16</p><div class="choice-list payment-ticket-list">'+(tickets.length?tickets.map(t=>'<button class="choice" data-payment-detail="'+t.id+'"><div class="payment-ticket-main"><strong>'+esc(t.customer||'Walk-in / unassigned')+'</strong><small>'+ticketNumber(t)+' · '+esc(t.plate||'No plate')+' · '+esc(t.time)+'</small><small>'+esc(t.material)+' · '+fmt(net(t))+' kg</small></div><div class="payment-ticket-amount"><strong>'+money(total(t))+'</strong><small>'+(t.payment==='unpaid'?'Payment due':'Paid · '+esc(t.payment))+' →</small></div></button>').join(''):'<div class="empty">No tickets in this category.</div>')+'</div>','PAYMENT RECORDS');
}
function paymentDetail(id){
 const t=getTicket(id);if(!t)return;selectedTicket=t.id;
 const activity=t.paymentActivity||[];
 modal('Payment details','<button class="text-button" data-payment-back="list">← Back to payments</button><div class="payment-detail-total"><span class="pill '+(t.payment==='unpaid'?'':'good')+'">'+(t.payment==='unpaid'?'Payment due':'Paid · '+esc(t.payment))+'</span><strong>'+money(total(t))+'</strong><small>CAD · includes GST</small></div><div class="detail-list">'+[['Ticket',ticketNumber(t)],['Customer',t.customer||'Walk-in / unassigned'],['Ticket date',t.date+' · '+t.time],['Payment method',t.payment==='unpaid'?'Not collected':t.payment],['Payment recorded',t.paidAt?new Date(t.paidAt).toLocaleString('en-CA',{timeZone:'America/Edmonton'})+' (Edmonton)':'Not recorded'],['Payment reference',t.paymentReference||'Not recorded in sample data'],['Material',t.material],['Gross / tare',fmt(t.gross)+' / '+fmt(t.tare)+' kg'],['Net material',fmt(net(t))+' kg'],['Rate',money(t.rate)+' / kg'],['Subtotal',money(net(t)*t.rate)],['GST (5%)',money(net(t)*t.rate*.05)]].map(([label,value])=>'<div><span>'+label+'</span><strong>'+esc(value)+'</strong></div>').join('')+vehicleReceiptRows(t)+'</div><form id="payment-note-form" data-ticket="'+t.id+'"><label class="field">Payment notes<textarea name="paymentNotes" maxlength="2000" placeholder="Reference, customer follow-up or payment instructions">'+esc(t.paymentNotes||'')+'</textarea></label><button class="button" type="submit">Save payment notes</button></form><details style="margin-top:20px"><summary class="text-button">Payment activity</summary>'+(activity.length?activity.map(a=>'<div class="activity-line">'+esc(new Date(a.at).toLocaleString('en-CA',{timeZone:'America/Edmonton'}))+' · '+esc(a.text)+' · '+esc(a.operator)+'</div>').join(''):'<p class="settings-note">No payment activity timestamps are available for this original sample record.</p>')+'</details><div class="modal-actions"><button class="button" data-payment-ticket="'+t.id+'">Open full ticket</button><button class="button" data-payment-receipt="'+t.id+'">View receipt</button>'+(t.payment==='unpaid'?'<button class="button primary" data-pay="'+t.id+'">Collect payment →</button>':'<button class="button primary" data-action="print-preview">Reprint receipt</button>')+'</div><p class="screen-only-note">Prototype only. No real payments or refunds are processed.</p>','PAYMENT RECORD');
}
function addPaymentReturn(id){const button=document.createElement('button');button.type='button';button.className='text-button';button.dataset.paymentDetail=id;button.textContent='← Back to payment details';$('modal-body').prepend(button)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.paymentList)return paymentList(b.dataset.paymentList);if(b.dataset.paymentDetail)return paymentDetail(b.dataset.paymentDetail);if(b.dataset.paymentBack==='summary')return settlement();if(b.dataset.paymentBack==='list')return paymentList(paymentListFilter);if(b.dataset.paymentTicket){detail(b.dataset.paymentTicket);addPaymentReturn(b.dataset.paymentTicket)}if(b.dataset.paymentReceipt){receipt(b.dataset.paymentReceipt);addPaymentReturn(b.dataset.paymentReceipt)}});
document.addEventListener('submit',e=>{if(e.target.id!=='payment-note-form')return;e.preventDefault();const t=getTicket(e.target.dataset.ticket),notes=String(new FormData(e.target).get('paymentNotes')||'').trim();if(notes===(t.paymentNotes||''))return toast('No changes to save.');t.paymentNotes=notes;t.paymentActivity=t.paymentActivity||[];t.paymentActivity.push({at:new Date().toISOString(),text:'Payment notes updated',operator:'EG'});save();paymentDetail(t.id);toast('Payment notes saved.')});
